{
  "model": "qwen/qwen3.5-27b-q6_k_l",
  "messages": [
    {
      "role": "system",
      "content": "You are a creative project orchestrator for CANVAS agency. Given a creative brief, decompose it into specific tasks for specialist agents. Return ONLY valid JSON, no preamble.\n\nAgents: research_agent, writer_agent, code_agent, data_agent, dataviz_agent, td_agent, critique_agent, qa_agent\n\nSchema:\n{\n  \"goal\": \"one sentence summary\",\n  \"tasks\": [{ \"agent\": \"\", \"task\": \"\", \"depends_on\": [], \"parallel_with\": [] }],\n  \"approval_required\": true,\n  \"approval_question\": \"question for human\",\n  \"confidence\": 0-100\n}"
    },
    {
      "role": "user",
      "content": "={{ $json.body.prompt }}"
    }
  ],
  "temperature": 0.3,
  "max_tokens": 4096,
  "stream": false
}

parameters.jsCode:
// ── Parse & Validate Orchestrator Response ──
const httpResponse = $input.first().json;

// Extract the assistant's message from the LM Studio response
let rawContent = '';
try {
  rawContent = httpResponse.choices[0].message.content;
} catch (e) {
  throw new Error('Invalid LM Studio response format: missing choices[0].message.content');
}

// Clean the response — strip markdown code fences if present
let cleaned = rawContent.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
}

// Parse JSON
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Failed to parse orchestrator JSON: ${e.message}\nRaw: ${rawContent.substring(0, 500)}`);
}

// Validate required top-level fields
const requiredFields = ['goal', 'tasks', 'approval_required', 'confidence'];
const missing = requiredFields.filter(f => !(f in parsed));
if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Validate tasks array
if (!Array.isArray(parsed.tasks)) {
  throw new Error('"tasks" must be an array');
}
if (parsed.tasks.length === 0) {
  throw new Error('"tasks" array is empty — at least one task is required');
}

const validAgents = ['research_agent', 'writer_agent', 'code_agent', 'data_agent', 'dataviz_agent', 'td_agent', 'critique_agent', 'qa_agent'];
for (let i = 0; i < parsed.tasks.length; i++) {
  const task = parsed.tasks[i];
  if (!task.agent || !validAgents.includes(task.agent)) {
    throw new Error(`Task ${i}: invalid or missing agent "${task.agent}". Must be one of: ${validAgents.join(', ')}`);
  }
  if (!task.task || typeof task.task !== 'string') {
    throw new Error(`Task ${i}: missing or invalid "task" description`);
  }
  // Ensure depends_on and parallel_with are arrays
  if (!Array.isArray(task.depends_on)) task.depends_on = [];
  if (!Array.isArray(task.parallel_with)) task.parallel_with = [];
}

// Validate confidence
if (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 100) {
  throw new Error('"confidence" must be a number between 0 and 100');
}

// Check confidence threshold from input
const threshold = $input.first().json.body?.confidence_threshold ?? 50;
if (parsed.confidence < threshold) {
  throw new Error(`Confidence (${parsed.confidence}) is below threshold (${threshold}). Refusing to proceed.`);
}

// Enrich with session metadata
const enriched = {
  ...parsed,
  session_id: $input.first().json.body?.session_id || ('canvas-' + Date.now()),
  mode: $input.first().json.body?.mode || 'collaborative',
  status: 'awaiting_approval',
  created_at: new Date().toISOString(),
  orchestrator_model: 'qwen/qwen3.5-27b-q6_k_l'
};

return [{ json: enriched }];
